-- Daily backups of each organization (the worker, at 00:00 Brasília time), a manual one on demand, and the safety copy
-- taken right before a restore. The register lives here; the file itself is kept outside the database, in the private
-- storage, so losing the database does not lose the copies.
--   daily          generated by the worker every night
--   manual         "Fazer backup agora" by the admin
--   before_restore automatic, right before a restore, so the restore itself can be undone
-- A copy that passed its retention (the plan's days) is removed from the storage and the row becomes 'expired': rows are never deleted.
-- This is the only hard deletion in the system and it only ever touches backup copies.

CREATE TABLE organization_backups (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id  UUID NOT NULL REFERENCES organizations (id),
  kind             VARCHAR(16) NOT NULL DEFAULT 'daily' CHECK (kind IN ('daily', 'manual', 'before_restore')),
  status           VARCHAR(16) NOT NULL DEFAULT 'running' CHECK (status IN ('running', 'completed', 'failed', 'expired')),
  backup_date      DATE NOT NULL,
  storage_url      TEXT,
  size_bytes       BIGINT NOT NULL DEFAULT 0,
  row_counts       JSONB NOT NULL DEFAULT '{}'::jsonb,
  error            TEXT,
  created_by       UUID,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  completed_at     TIMESTAMPTZ,
  expired_at       TIMESTAMPTZ,
  restored_at      TIMESTAMPTZ,
  restored_by      UUID,
  restore_summary  JSONB
);

-- one nightly copy per organization per day (a failed attempt does not block the next one)
CREATE UNIQUE INDEX organization_backups_daily_key
  ON organization_backups (organization_id, backup_date)
  WHERE kind = 'daily' AND status IN ('running', 'completed');

CREATE INDEX organization_backups_org_created_idx ON organization_backups (organization_id, created_at DESC);
